# ============================================================================
# ars.R -- Adaptive Rejection Sampling (Gilks & Wild 1992)
#
# Adaptive rejection sampling for a one-dimensional log-concave target
# density.  The user supplies a (vectorized) function evaluating the
# (possibly unnormalized) density, e.g. dnorm, dexp, dgamma.  Internally we
# work with the log-density h(x) = log f(x) and numerical slopes h'(x).
#
# Design (one small function per task, consistent naming: x = points,
# h = log-density values, s = slopes, env = envelope state list):
#
#   validate_ars_input    check user arguments
#   make_log_density      wrap f so that h = log f, with positivity checks
#   estimate_slope        numeric derivative of h (central / one-sided)
#   choose_initial_points locate the starting set of points
#   tangent_crossing      x-intersection of two tangents
#   build_envelope        piecewise-linear upper hull u (list of segments)
#   segment_log_area      log of the integral of exp(line) over a segment
#   envelope_log_areas    log normalizing constants for every segment
#   sample_envelope       draw a candidate z from the envelope
#   envelope_at           value u(z) of the upper envelope
#   squeeze_at            value l(z) of the lower (squeezing) envelope
#   check_log_concavity   runtime tests that fire on non-log-concave input
#   ars                   main driver
#   test                  formal tests against known distributions
#
# Reference: Gilks, W. R., & Wild, P. (1992). Adaptive rejection sampling for
# Gibbs sampling. Journal of the Royal Statistical Society: Series C
# (Applied Statistics), 41(2), 337-348.
# ============================================================================

# Tolerance for the log-concavity checks (relative to local scale).
.LTOL <- 1e-6
# Relative step for the numerical derivative of the log-density.
.SLOPE_STEP <- 1e-5

# ----------------------------------------------------------------------------
# Input validation
# ----------------------------------------------------------------------------
validate_ars_input <- function(n, f, support, init, max_iter) {
  if (!is.numeric(n) || length(n) != 1L || is.na(n) || !is.finite(n) ||
      n < 1 || n != floor(n)) {
    stop("ars: 'n' must be a positive integer (got: ",
         paste(format(n), collapse = ","), ")", call. = FALSE)
  }
  n <- as.integer(n)

  if (!is.function(f)) {
    stop("ars: 'f' must be a (vectorized) function evaluating the ",
         "(unnormalized) density, e.g. dnorm", call. = FALSE)
  }

  if (!is.numeric(support) || length(support) != 2L || any(is.na(support)) ||
      support[1] >= support[2]) {
    stop("ars: 'support' must be a length-2 numeric vector (l < u); ",
         "-Inf / Inf are allowed for unbounded domains", call. = FALSE)
  }

  if (!is.null(init)) {
    if (!is.numeric(init) || length(init) < 2L || any(is.na(init))) {
      stop("ars: 'init' must be a numeric vector of at least 2 non-NA points",
           call. = FALSE)
    }
    if (any(init <= support[1] || init >= support[2])) {
      stop("ars: 'init' points must lie strictly inside 'support'",
           call. = FALSE)
    }
  }

  if (is.null(max_iter)) {
    max_iter <- 1000L * n + 10000L
  } else if (!is.numeric(max_iter) || length(max_iter) != 1L ||
             is.na(max_iter) || !is.finite(max_iter) ||
             max_iter < n || max_iter != floor(max_iter)) {
    stop("ars: 'max_iter' must be an integer at least as large as 'n'",
         call. = FALSE)
  }
  max_iter <- as.integer(max_iter)

  list(n = n, support = support, init = init, max_iter = max_iter)
}

# ----------------------------------------------------------------------------
# Log-density wrapper and numerical slope
# ----------------------------------------------------------------------------
make_log_density <- function(f) {
  function(x) {
    x <- as.numeric(x)
    fx <- f(x)
    if (length(fx) == 1L && length(x) > 1L) {
      # f was not vectorized: evaluate pointwise as a fallback
      fx <- vapply(x, function(v) f(v), numeric(1L))
    }
    if (!is.numeric(fx) || length(fx) != length(x)) {
      stop("ars: the density function must return one numeric value per input",
           call. = FALSE)
    }
    if (any(is.nan(fx))) {
      stop("ars: the density function returned NaN", call. = FALSE)
    }
    if (any(fx < 0)) {
      stop("ars: the density function returned a negative value; a density ",
           "must be non-negative", call. = FALSE)
    }
    h <- rep(-Inf, length(x))
    pos <- fx > 0
    h[pos] <- log(fx[pos])
    h
  }
}

estimate_slope <- function(h, x) {
  step <- .SLOPE_STEP * max(1, abs(x))
  hp <- h(x + step)
  hm <- h(x - step)
  if (is.finite(hp) && is.finite(hm)) {
    (hp - hm) / (2 * step)
  } else if (is.finite(hp)) {
    (hp - h(x)) / step                    # one-sided (left out of domain)
  } else if (is.finite(hm)) {
    (h(x) - hm) / step                    # one-sided (right out of domain)
  } else {
    stop("ars: the log-density is not finite at x = ", format(x),
         " (or its neighbourhood); cannot estimate the slope",
         call. = FALSE)
  }
}

# ----------------------------------------------------------------------------
# Initial set of points
# ----------------------------------------------------------------------------
choose_initial_points <- function(h, slope, support, init) {
  if (!is.null(init)) {
    x <- sort(unique(as.numeric(init)))
    hx <- vapply(x, h, numeric(1L))
    if (any(!is.finite(hx))) {
      stop("ars: the density must be positive at every 'init' point ",
           "(log-density is -Inf there)", call. = FALSE)
    }
    sx <- vapply(x, slope, numeric(1L))
    if (is.infinite(support[1]) && sx[1] <= 0) {
      stop("ars: with an unbounded lower bound the leftmost 'init' point ",
           "needs a positive log-density slope (the points must bracket the mode)",
           call. = FALSE)
    }
    if (is.infinite(support[2]) && sx[length(sx)] >= 0) {
      stop("ars: with an unbounded upper bound the rightmost 'init' point ",
           "needs a negative log-density slope (the points must bracket the mode)",
           call. = FALSE)
    }
    return(list(x = x, h = hx, s = sx))
  }

  # Automatic: probe around 0 until we find usable points.
  cands <- c(0, 1, -1, 2, -2, 4, -4, 8, -8, 16, -16, 32, -32, 64, -64, 128, -128)
  cands <- cands[cands > support[1] & cands < support[2]]
  hx <- vapply(cands, h, numeric(1L))
  ok <- is.finite(hx)
  if (sum(ok) < 2L) {
    stop("ars: could not find two points with positive density inside ",
         "'support'; supply 'init' points", call. = FALSE)
  }
  sl <- vapply(cands[ok], slope, numeric(1L))
  cx <- cands[ok]

  # Leftmost point: any finite point if the left bound is finite, otherwise
  # the first (smallest) candidate with positive slope.
  xl <- NA_real_
  for (i in seq_along(cx)) {
    if (is.finite(support[1]) || sl[i] > 0) { xl <- cx[i]; break }
  }
  # Rightmost point: symmetric, and strictly to the right of the left point.
  xr <- NA_real_
  for (i in seq_along(cx)) {
    if (cx[i] <= xl) next
    if (is.finite(support[2]) || sl[i] < 0) { xr <- cx[i]; break }
  }
  if (is.na(xl) || is.na(xr)) {
    stop("ars: could not auto-locate initial points bracketing the mode ",
         "(an unbounded side needs a positive slope at the leftmost point and ",
         "a negative slope at the rightmost point); supply 'init' points",
         call. = FALSE)
  }
  list(x = c(xl, xr), h = c(h(xl), h(xr)),
       s = vapply(c(xl, xr), slope, numeric(1L)))
}

# ----------------------------------------------------------------------------
# Upper envelope: piecewise-linear upper hull u built from the tangents
# ----------------------------------------------------------------------------
tangent_crossing <- function(x1, h1, s1, x2, h2, s2) {
  if (abs(s1 - s2) < 1e-12) return((x1 + x2) / 2)   # (near-)parallel tangents
  (h2 - h1 + s1 * x1 - s2 * x2) / (s1 - s2)
}

build_envelope <- function(x, h, s, support) {
  npts <- length(x)
  segs <- list()
  add_seg <- function(a, b, sl, icpt) {
    if (b <= a) return(invisible())   # skip empty segments
    segs[[length(segs) + 1L]] <<- list(a = a, b = b, s = sl, i = icpt)
  }
  # left tail: tangent at the leftmost point
  add_seg(support[1], x[1], s[1], h[1] - s[1] * x[1])
  # between successive points: max of the two adjacent tangents
  for (i in seq_len(npts - 1L)) {
    cross <- tangent_crossing(x[i], h[i], s[i], x[i + 1L], h[i + 1L], s[i + 1L])
    if (cross <= x[i]) {
      add_seg(x[i], x[i + 1L], s[i], h[i] - s[i] * x[i])
    } else if (cross >= x[i + 1L]) {
      add_seg(x[i], x[i + 1L], s[i + 1L], h[i + 1L] - s[i + 1L] * x[i + 1L])
    } else {
      add_seg(x[i], cross, s[i + 1L], h[i + 1L] - s[i + 1L] * x[i + 1L])
      add_seg(cross, x[i + 1L], s[i], h[i] - s[i] * x[i])
    }
  }
  # right tail: tangent at the rightmost point
  add_seg(x[npts], support[2], s[npts], h[npts] - s[npts] * x[npts])
  list(segs = segs, x = x, h = h, s = s, support = support)
}

segment_log_area <- function(a, b, s, icpt) {
  # log of  Integral_a^b exp(icpt + s t) dt
  if (is.infinite(a) && is.infinite(b)) {
    stop("ars: the upper envelope is not integrable over the support",
         call. = FALSE)
  }
  if (abs(s) < 1e-12) {
    if (is.infinite(a) || is.infinite(b)) {
      stop("ars: the upper envelope is flat over an unbounded region and is ",
           "not integrable; the initial points must bracket the mode ",
           "(positive slope at the leftmost point, negative at the rightmost)",
           call. = FALSE)
    }
    return(icpt + log(b - a))
  }
  ua <- icpt + s * a
  ub <- icpt + s * b
  m <- max(ua, ub)
  if (is.infinite(m)) {
    stop("ars: the upper envelope is not integrable; the outermost slope must ",
         "point into the support (initial points must bracket the mode)",
         call. = FALSE)
  }
  d <- abs(ua - ub)
  if (d < 1e-8) {
    return(m + log(d) - log(abs(s)))        # nearly constant: area ~ exp(m)*d/|s|
  }
  m + log1p(-exp(-d)) - log(abs(s))
}

envelope_log_areas <- function(env) {
  vapply(env$segs, function(sg) segment_log_area(sg$a, sg$b, sg$s, sg$i),
         numeric(1L))
}

envelope_at <- function(z, env) {
  nseg <- length(env$segs)
  for (j in seq_len(nseg)) {
    sg <- env$segs[[j]]
    if (z >= sg$a && (z < sg$b || (j == nseg && z <= sg$b))) {
      return(sg$i + sg$s * z)
    }
  }
  stop("ars: internal error: point z = ", format(z),
       " lies outside the envelope", call. = FALSE)
}

sample_envelope <- function(env) {
  la <- envelope_log_areas(env)
  m <- max(la)
  if (is.infinite(m) || m == -Inf) {
    stop("ars: the upper envelope has zero or infinite total area",
         call. = FALSE)
  }
  p <- exp(la - m)
  p <- p / sum(p)
  idx <- sample.int(length(p), 1L, prob = p)
  sg <- env$segs[[idx]]
  a <- sg$a; b <- sg$b; s <- sg$s
  if (abs(s) < 1e-12) {
    if (is.infinite(a) || is.infinite(b)) {
      stop("ars: the envelope is flat over an unbounded segment", call. = FALSE)
    }
    z <- a + runif(1L) * (b - a)
  } else if (is.finite(a) && is.finite(b)) {
    len <- b - a
    if (abs(s) * len < 1e-8) {
      z <- a + runif(1L) * len
    } else {
      xm <- if (s > 0) b else a
      z <- xm - log(1 - runif(1L) * (1 - exp(-abs(s) * len))) / abs(s)
    }
  } else if (is.infinite(b)) {
    if (s >= 0) stop("ars: the envelope is not integrable on the right tail",
                     call. = FALSE)
    z <- a - log(1 - runif(1L)) / abs(s)
  } else {
    if (s <= 0) stop("ars: the envelope is not integrable on the left tail",
                     call. = FALSE)
    z <- b + log(runif(1L)) / s
  }
  list(z = z, u = sg$i + sg$s * z)
}

# ----------------------------------------------------------------------------
# Lower (squeezing) envelope: chords between adjacent points, -Inf elsewhere
# ----------------------------------------------------------------------------
squeeze_at <- function(z, x, h) {
  i <- findInterval(z, x)
  if (i < 1L || i >= length(x)) return(-Inf)
  h[i] + (z - x[i]) * (h[i + 1L] - h[i]) / (x[i + 1L] - x[i])
}

# ----------------------------------------------------------------------------
# Log-concavity checks (run whenever a new point is added to the hull)
# ----------------------------------------------------------------------------
check_log_concavity <- function(z, hz, sz, env) {
  uz <- envelope_at(z, env)
  tol <- .LTOL * max(1, abs(hz), abs(uz))

  # (a) the tangent at the new point must not rise above the current upper
  #     envelope (a tangent of a concave function is a global upper bound)
  if (hz > uz + tol) {
    stop("ars: log-density appears NOT to be concave: h(", format(z),
         ") = ", format(hz), " exceeds the upper envelope value ",
         format(uz), "; stopping the sampling", call. = FALSE)
  }

  # (b) slopes must be non-increasing in x
  i <- findInterval(z, env$x)
  s <- env$s
  if (i < 1L) {
    if (sz < s[1] - tol) {
      stop("ars: log-density appears NOT to be concave: slope ", format(sz),
           " at x = ", format(z), " is below the slope ", format(s[1]),
           " at x = ", format(env$x[1]), " (slopes must decrease in x); ",
           "stopping the sampling", call. = FALSE)
    }
  } else if (i >= length(env$x)) {
    if (sz > s[length(s)] + tol) {
      stop("ars: log-density appears NOT to be concave: slope ", format(sz),
           " at x = ", format(z), " is above the slope ",
           format(s[length(s)]), " at x = ", format(env$x[length(env$x)]),
           " (slopes must decrease in x); stopping the sampling",
           call. = FALSE)
    }
  } else if (sz > s[i] + tol || sz < s[i + 1L] - tol) {
    stop("ars: log-density appears NOT to be concave: slope ", format(sz),
         " at x = ", format(z), " breaks the decreasing order between slopes ",
         format(s[i]), " and ", format(s[i + 1L]), "; stopping the sampling",
         call. = FALSE)
  }
  invisible(TRUE)
}

# ----------------------------------------------------------------------------
# Main driver: adaptive rejection sampling
# ----------------------------------------------------------------------------
ars <- function(n, f, support = c(-Inf, Inf), init = NULL, max_iter = NULL) {
  v <- validate_ars_input(n, f, support, init, max_iter)
  n <- v$n
  support <- v$support

  h <- make_log_density(f)
  slope <- function(x) estimate_slope(h, x)

  st <- choose_initial_points(h, slope, support, v$init)
  env <- build_envelope(st$x, st$h, st$s, support)

  samples <- numeric(0L)
  for (iter in seq_len(v$max_iter)) {
    if (length(samples) == n) break

    cand <- sample_envelope(env)
    z <- cand$z
    uz <- cand$u
    r <- runif(1L)

    # squeezing step: accept without evaluating the density
    lz <- squeeze_at(z, env$x, env$h)
    if (is.finite(lz) && lz <= uz && r <= exp(lz - uz)) {
      samples <- c(samples, z)
      next
    }

    hz <- h(z)
    if (!is.finite(hz)) next              # zero density: reject, no insertion

    sz <- slope(z)
    if (!is.finite(sz)) next              # slope not estimable: reject only

    # runtime log-concavity checks (stop() if violated)
    check_log_concavity(z, hz, sz, env)

    if (r <= exp(hz - uz)) samples <- c(samples, z)

    # adaptive step: insert the newly evaluated point into the hull
    env <- build_envelope(
      x = sort(c(env$x, z)),
      h = c(env$h, hz)[order(c(env$x, z))],
      s = c(env$s, sz)[order(c(env$x, z))],
      support = support
    )
  }

  if (length(samples) < n) {
    stop("ars: reached max_iter = ", v$max_iter, " without obtaining n = ",
         n, " samples; increase 'max_iter'", call. = FALSE)
  }
  samples
}
